patches.content:
// idle_modes: three-state idle mode. "off" locks, turns the screen off
// and suspends when idle; "half" locks and turns the screen off but never
// suspends (the hypridle suspend listener reads the module config);
// "full" inhibits idle entirely. The idle_modes window entry restores the
// mode from its config file at every shell start.
property string idleMode: "off"
property bool idleModesActive: false

function setIdleMode(mode) {
    const next = ["off", "half", "full"].includes(mode) ? mode : "off";
    root.idleMode = next;
    root.inhibit = next === "full";
    Persistent.states.idle.inhibit = root.inhibit;
}

function cycleIdleMode() {
    root.setIdleMode(root.idleMode === "off" ? "half" : root.idleMode === "half" ? "full" : "off");
}

// idle_modes: a plain toggle cycles the mode; an explicit request
// (lock screen "unlock and keep awake") maps to full or off.
if (root.idleModesActive) {
    if (active === null)
        root.cycleIdleMode();
    else
        root.setIdleMode(active ? "full" : "off");
    return;
}

// idle_modes: Hyprland judges an inhibitor's surface visibility only
// when the inhibitor is created (and on focus or window events), not
// when a layer surface maps. When "full" is restored at shell start,
// the inhibitor binds before this 0x0 surface maps and stays
// ineffective until the next focus change, so hypridle still locks
// and suspends. Re-create it once the surface has had time to map.
// Toggling enabled re-emits windowChanged, so the timer is started
// from the visibility signal rather than bound to the window.
property Timer idleModesRearm: Timer {
    interval: 3000
    onTriggered: {
        if (!idleInhibitor.enabled)
            return;
        idleInhibitor.enabled = false;
        idleInhibitor.enabled = true;
    }
}
property Connections idleModesRearmTrigger: Connections {
    target: idleInhibitor.window
    function onBackingWindowVisibleChanged() {
        if (idleInhibitor.window.backingWindowVisible)
            idleInhibitor.idleModesRearm.restart();
    }
}

id: idleModesToggle

// idle_modes: show the three-state idle mode on the tile.
Binding {
    target: idleModesToggle
    when: Idle.idleModesActive
    property: "toggled"
    value: Idle.idleMode !== "off"
}
Binding {
    target: idleModesToggle
    when: Idle.idleModesActive
    property: "icon"
    value: Idle.idleMode === "half" ? "bedtime_off" : "coffee"
}
Binding {
    target: idleModesToggle
    when: Idle.idleModesActive
    property: "statusText"
    value: Idle.idleMode === "full" ? Translation.tr("Always on") : Idle.idleMode === "half" ? Translation.tr("Screen off only") : Translation.tr("Sleeps when idle")
}
Binding {
    target: idleModesToggle
    when: Idle.idleModesActive
    property: "tooltipText"
    value: Translation.tr("Click to cycle: sleeps when idle, screen off only, always on")
}
